import { getEncoding } from "js-tiktoken";
const enc = getEncoding("o200k_base"); // открытый токенайзер OpenAI

const doc = [
  "# Refunds",
  "Annual plans can be refunded within 30 days of purchase. Monthly plans are not refundable, but you can cancel at any time and keep access until the end of the billing period.",
  "",
  "# Security",
  "We store passwords with bcrypt. Two-factor authentication is available on all plans and is required for admin accounts.",
].join("\n"); // 64 токена

function fixedChunks(text, size, overlap = 0) {
  const ids = enc.encode(text);
  const step = size - overlap; // шаг: размер минус перекрытие
  const chunks = [];
  for (let start = 0; start < ids.length; start += step) {
    chunks.push(enc.decode(ids.slice(start, start + size)));
    if (start + size >= ids.length) break;
  }
  return chunks;
}

fixedChunks(doc, 30).forEach((c, i) => console.log(i, JSON.stringify(c)));

// Сначала режем по заголовкам, большой раздел добиваем fixed size с перекрытием 15%
function structuralChunks(text, maxTokens) {
  const sections = text.split(/\n(?=# )/);
  return sections.flatMap((s) => {
    const title = s.match(/^# (.*)/)?.[1] ?? "";
    const n = enc.encode(s).length;
    const parts = n <= maxTokens
      ? [s]
      : fixedChunks(s, maxTokens, Math.floor(maxTokens * 0.15)); // потолок по размеру
    return parts.map((p, i) => ({ section: title, part: i, tokens: enc.encode(p).length, text: p }));
  });
}

// Вывод structuralChunks(doc, 60): раздел, номер части, токенов, текст
// Refunds  0 40 "# Refunds\nAnnual plans can be refunded within 30 days ... end of the billing period.\n"
// Security 0 24 "# Security\nWe store passwords with bcrypt. Two-factor ... required for admin accounts."

import { RecursiveCharacterTextSplitter } from "@langchain/textsplitters";

// chunkSize считается в СИМВОЛАХ, не в токенах
const splitter = new RecursiveCharacterTextSplitter({ chunkSize: 100, chunkOverlap: 20 });
(await splitter.splitText(doc)).forEach((c, i) => console.log(i, c.length, JSON.stringify(c)));

