// Золотой набор: вопрос и id куска, где лежит ответ
const golden = [
  { q: "Can I get a refund on an annual plan?", gold: "refunds#0" },
  { q: "Do I keep access after cancelling?", gold: "refunds#0" },
  { q: "Is 2FA mandatory for admins?", gold: "security#0" },
  { q: "How are passwords stored?", gold: "security#0" },
];

// Что вернул ретривер, лучшие первыми (в реальности из векторного поиска)
const retrieved = {
  "Can I get a refund on an annual plan?": ["refunds#0", "security#0"],
  "Do I keep access after cancelling?": ["security#0", "refunds#0"],
  "Is 2FA mandatory for admins?": ["refunds#0", "security#0"],
  "How are passwords stored?": ["security#0", "refunds#0"],
};

function recallAtK(k) {
  const hits = golden.filter(({ q, gold }) => retrieved[q].slice(0, k).includes(gold));
  return hits.length / golden.length;
}

